p=argparse.ArgumentParser();p.add_argument('--scored',type=Path,required=True);p.add_argument('--prepared',type=Path,required=True);p.add_argument('--decision',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();O=a.output;O.mkdir(parents=True,exist_ok=True);s=pl.read_parquet(a.scored);nt=pl.read_parquet(a.prepared/'ntrue.parquet');cfg=json.loads(a.decision.read_text());sel=accepted(s,cfg);truth=pl.read_parquet(R/'work/cache/gt_pairs.parquet').join(nt.select('s1'),on='s1',how='semi');counts=nt.join(sel.group_by('s1').agg(pl.col('label').sum().alias('tp'),pl.len().alias('npred')),on='s1',how='left').fill_null(0);fv,pr,re,sg=E.macro_f05_from_counts(*[counts[c].to_numpy() for c in ['tp','npred','ntrue']]);counts=counts.with_columns(pl.Series('f05',fv),pl.Series('precision',pr),pl.Series('recall',re));errors=counts.filter(pl.col('f05')<1-1e-12);blocked=truth.join(s.select(KEY),on=KEY,how='anti').with_columns(pl.lit('A_blocking').alias('error'));rejected=s.filter(pl.col('label')==1).join(sel.select(KEY),on=KEY,how='anti').select(KEY).with_columns(pl.lit('B_matching_rejection').alias('error'));false=sel.filter(pl.col('label')==0).join(nt,on='s1').with_columns(pl.when(pl.col('ntrue')==0).then(pl.lit('D_singleton_false_match')).otherwise(pl.lit('C_false_merge')).alias('error')).select(*KEY,'error');cases=pl.concat([blocked,rejected,false]);summary=cases.group_by('error').agg(pl.len().alias('pairs'),pl.col('s1').n_unique().alias('affected_s1')).with_columns((pl.col('pairs')/cases.height*100).alias('percent_pair_errors'),(pl.col('affected_s1')/errors.height*100).alias('percent_imperfect_entities_overlapping'));summary.write_csv(O/'pair_error_categories.csv')
